import React from "react";
import { useParams } from "react-router-dom";

const MaterialPage = () => {
  const { id } = useParams();

  // Materiais separados por ID (poderia vir de um banco futuramente)
  const materiaisPorModulo = {
    1: [
      { titulo: "Guia de Boas-Vindas", tipo: "PDF", tamanho: "1.2 MB" },
      { titulo: "Apresentação – Aula 01", tipo: "Slides", tamanho: "2.1 MB" },
    ],
    2: [
      { titulo: "Manual de Liderança", tipo: "PDF", tamanho: "2.3 MB" },
      { titulo: "Atividades – Aula 02", tipo: "Excel", tamanho: "900 KB" },
    ],
    3: [
      { titulo: "Guia de Desenvolvimento", tipo: "PDF", tamanho: "1.8 MB" },
    ],
  };

  const materiais = materiaisPorModulo[id] || [];

  return (
    <main className="flex min-h-screen bg-[#FAF9F7] font-[Poppins,sans-serif]">
      {/* Painel lateral */}
      <aside className="w-72 bg-gradient-to-b from-[#B95758] to-[#e14d3a] text-white p-6 fixed top-0 left-0">
        <div>
          <h2 className="text-lg font-bold mb-6 uppercase">Módulos</h2>
          <ul className="space-y-3 text-sm">
            <li className="hover:text-yellow-200 cursor-pointer">Aula 01 – Bem Vindo</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 02 – Liderança</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 03 – Desenvolvimento</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 04 – Propósito</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 05 – Estilos</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 06 – Bônus</li>
          </ul>
        </div>

        <button className="w-full bg-white text-[#B95758] font-semibold py-2 rounded-md hover:bg-gray-100 transition">
          Material de Apoio
        </button>
      </aside>

      {/* Conteúdo principal */}
      <section className="flex-1 p-10">
        <h1 className="text-3xl font-bold text-center mb-10">
          📚 Materiais de Apoio – Aula {id}
        </h1>

        {materiais.length === 0 ? (
          <p className="text-center text-gray-500 text-lg">
            Nenhum material disponível para este módulo.
          </p>
        ) : (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">
            {materiais.map((m, i) => (
              <div
                key={i}
                className="bg-white shadow-lg rounded-xl p-6 flex flex-col items-center text-center hover:shadow-xl transition duration-300"
              >
                <img
                  src="https://cdn-icons-png.flaticon.com/512/337/337946.png"
                  alt="Material"
                  className="w-20 mb-4"
                />
                <h3 className="font-semibold text-gray-800 mb-2">{m.titulo}</h3>
                <p className="text-gray-500 text-sm mb-4">
                  {m.tipo} • {m.tamanho}
                </p>
                <button className="bg-[#B95758] text-white px-5 py-2 rounded-lg font-medium hover:bg-[#e14d3a] transition duration-300">
                  Baixar
                </button>
              </div>
            ))}
          </div>
        )}
      </section>
    </main>
  );
};

export default MaterialPage;
